const items=[{id:1,name:'Запись A',state:'Черновик'},{id:2,name:'Запись B',state:'Активна'},{id:3,name:'Запись C',state:'На проверке'}];const host=document.querySelector('#items');const modal=document.querySelector('#details');function render(q=''){host.replaceChildren();const list=items.filter(x=>x.name.toLowerCase().includes(q.toLowerCase()));if(!list.length){const e=document.createElement('p');e.textContent='Ничего не найдено';host.append(e);return}for(const x of list){const a=document.createElement('article');a.className='item';const c=document.createElement('div');const h=document.createElement('h3');h.textContent=x.name;const p=document.createElement('p');p.textContent=x.state;c.append(h,p);const b=document.createElement('button');b.textContent='Открыть';b.addEventListener('click',()=>{document.querySelector('#detail-title').textContent=x.name;document.querySelector('#detail-text').textContent=`Состояние: ${x.state}. Данные демонстрационные.`;modal.showModal()});a.append(c,b);host.append(a)}}document.querySelector('#query').addEventListener('input',e=>render(e.target.value));document.querySelector('#add').addEventListener('click',()=>{items.push({id:Date.now(),name:`Запись ${items.length+1}`,state:'Черновик'});render(document.querySelector('#query').value)});render();
